from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        edges = defaultdict(list)
        degree = [0] * (n + 1)

        for _ in range(n - 1):
            u, v = read_ints()
            edges[u].append(v)
            edges[v].append(u)
            degree[u] += 1
            degree[v] += 1

        # Find all leaves
        leaves = [i for i in range(1, n + 1) if degree[i] == 1]

        # Count initial number of leaves
        initial_leaves = len(leaves)

        # If there are more than 2 leaves, we can always reduce the number of leaves by moving buds
        if initial_leaves > 2:
            print(n - initial_leaves + 1)
        else:
            print(1)

if __name__ == "__main__":
    main()
